/*
 * Patina — Aqua structure × millennium colour tones.
 * Source of truth: /DESIGN.md (Google DESIGN.md format). Keep the two in sync.
 *
 * Structure = Mac OS X Aqua (2000–2005): pinstripes, traffic lights, gel
 * buttons, brushed metal, a translucent Dock. It never changes.
 * Tone = the hue of everything gel and the wallpaper. Switch with
 * data-tone="pink|aqua|lime|tangerine|grape" on <html>. Pink is default.
 */

:root {
  color-scheme: light;

  /* ── Aqua constants (never toned) ─────────────────────────────── */
  --y2k-ink: #000000;
  --y2k-ink-secondary: #4b4b4b;
  --y2k-ink-disabled: #8d8d8d;
  /* Links: the one blue Aqua keeps in every tone (DESIGN.md secondary). */
  --y2k-link: #2765ca;
  /* Window titles: #2f2f2f lifted by a white 1px; #8a8a8a unfocused. */
  --y2k-title-ink: #2f2f2f;
  --y2k-title-ink-inactive: #8a8a8a;
  --y2k-title-lift: 0 1px 0 rgba(255, 255, 255, 0.7);
  --y2k-window-border: #7f7f7f;
  /* The one hairline: separators, a sidebar's edge, a sunken well's rim. */
  --y2k-separator: rgba(0, 0, 0, 0.2);
  --y2k-input-bg: #ffffff;

  /* ── Type ─────────────────────────────────────────────────────── */
  --y2k-font-ui: "Lucida Grande", "LucidaGrande", "AquaKana", var(--font-lato, "Lato"), "Lucida Sans Unicode", "Hiragino Sans", "Hiragino Sans GB", ui-sans-serif, system-ui, -apple-system, sans-serif;
  --y2k-font-wordmark: var(--font-eb-garamond, "EB Garamond"), "Apple Garamond", Garamond, "Times New Roman", serif;
  --y2k-font-mono: Monaco, ui-monospace, Menlo, "Courier New", monospace;

  /* ── Pinstripes (Aqua 10.0): 1px rows on a 4px period ──────────── */
  --y2k-pinstripe: repeating-linear-gradient(to bottom, #dedede 0 1px, #ebebeb 1px 2px, #dedede 2px 3px, #d7d7d7 3px 4px);
  /* The three surfaces by weight: light (menus, the menu bar, the Dock),
     regular (windows), dark (sheets). */
  --y2k-pinstripe-light: repeating-linear-gradient(to bottom, #fafafa 0 1px, #e9e9e9 1px 2px, #fafafa 2px 3px, #ffffff 3px 4px);
  /* An open menu: the light pinstripe at 90%, so the screen shows faintly
     through it, as 10.0's menus let it. */
  --y2k-pinstripe-menu: repeating-linear-gradient(to bottom, rgb(250 250 250 / 0.9) 0 1px, rgb(233 233 233 / 0.9) 1px 2px, rgb(250 250 250 / 0.9) 2px 3px, rgb(255 255 255 / 0.9) 3px 4px);
  /* The Dock shelf: 10.1's own rows at 55%, solved from the shelf over two
     wallpaper blues in Olivia's screenshot. */
  --y2k-pinstripe-dock: repeating-linear-gradient(to bottom, rgb(236 236 236 / 0.55) 0 1px, rgb(232 232 232 / 0.55) 1px 2px, rgb(236 236 236 / 0.55) 2px 3px, rgb(245 245 245 / 0.55) 3px 4px);
  --y2k-pinstripe-dark: repeating-linear-gradient(to bottom, #cfcfcf 0 1px, #d5d5d5 1px 2px, #e3e3e3 2px 3px, #d5d5d5 3px 4px);
  /* Status bar / placard: a lighter stripe. */
  --y2k-placard: repeating-linear-gradient(to bottom, #f1f1f1 0 1px, #ffffff 1px 2px, #f1f1f1 2px 3px, #eaeaea 3px 4px);
  --y2k-placard-inactive: repeating-linear-gradient(to bottom, #c9c9c9 0 1px, #d7d7d7 1px 2px, #c9c9c9 2px 3px, #c2c2c2 3px 4px);
  --y2k-menubar-border: #a0a0a0;
  --y2k-metal: url("data:image/png;base64,");

  /* ── Gel (buttons, popups, lights) ─────────────────────────────── */
  /* The row gradients themselves (--y2k-gel-white, --y2k-segment-white,
     --y2k-listheader, --y2k-check-off …) are generated from the measured
     10.0 controls into the measured:begin block below. */
  /* Push button: a deep soft drop, pulled in when pressed. */
  --y2k-shadow-button: 0 5px 10px rgba(0, 0, 0, 0.42), 0 2px 4px rgba(0, 0, 0, 0.32), 0 1px 2px rgba(0, 0, 0, 0.24), 0 1px 0 rgba(255, 255, 255, 0.5);
  --y2k-shadow-button-small: 0 4px 8px rgba(0, 0, 0, 0.38), 0 2px 3px rgba(0, 0, 0, 0.3), 0 1px 2px rgba(0, 0, 0, 0.22), 0 1px 0 rgba(255, 255, 255, 0.5);
  --y2k-shadow-button-active: 0 1px 2px rgba(0, 0, 0, 0.28), 0 1px 0 rgba(255, 255, 255, 0.35);
  /* The round ends darken toward the rim: 0.75 of the body at the edge,
     back to 0.97 seven pixels in (white); the tone gel darkens to 0.5. */
  --y2k-button-rim-white: inset 6px 0 6px -4px rgba(0, 0, 0, 0.3), inset -6px 0 6px -4px rgba(0, 0, 0, 0.3);
  /* Text fields: white, a soft rim darker on top, a short inner shadow. */
  --y2k-field-border: #a9a9a9;
  --y2k-field-border-top: #949494;
  --y2k-field-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.16);

  /* ── Scrollbar ─────────────────────────────────────────────────── */
  /* The trough, the arrow face and the tone thumb are measured columns,
     generated below. */
  --y2k-scrollbar-size: 15px;

  /* ── Traffic lights ───────────────────────────────────────────── */
  /* The gems themselves (--y2k-light-red/-yellow/-green/-off) are the
     measured rows, generated below. They sit on the reference's layered
     drop; the sides darken toward a near-black rim. */
  /* The gem drop — the title bar's toolbar oval sits on it too. */
  --y2k-light-drop: 0 0 1px rgba(0, 0, 0, 0.5), 0 1px 1px rgba(0, 0, 0, 0.55), 0 2px 3px rgba(0, 0, 0, 0.5), 0 3px 5px rgba(0, 0, 0, 0.35);
  --y2k-light-drop-active: 0 0 1px rgba(0, 0, 0, 0.4), 0 1px 1px rgba(0, 0, 0, 0.3);
  --y2k-light-rim: inset 0 0 0 1px rgba(0, 0, 0, 0.55), inset 0 0 4px rgba(0, 0, 0, 0.35);
  --y2k-light-shadow: var(--y2k-light-drop), var(--y2k-light-rim);
  --y2k-light-shadow-active: var(--y2k-light-drop-active), var(--y2k-light-rim);
  --y2k-light-red-glyph: rgba(130, 30, 20, 0.9);
  --y2k-light-yellow-glyph: rgba(130, 80, 8, 0.9);
  --y2k-light-green-glyph: rgba(45, 90, 18, 0.9);

  /* ── Elevation ────────────────────────────────────────────────── */
  /* Aqua window drop = two casts (a tight near shadow + a wide soft far one),
     plus a white inset top rim-light on the window edge. Alpha 0.7 per ryOS. */
  --y2k-shadow-window: 0 12px 28px rgba(0, 0, 0, 0.34), 0 2px 6px rgba(0, 0, 0, 0.2);
  --y2k-shadow-menu: 0 8px 20px rgba(0, 0, 0, 0.32);
  --y2k-shadow-dock: 0 2px 8px rgba(0, 0, 0, 0.15);
  --y2k-metal-inset: inset 0 2px 2px rgba(255, 255, 255, 0.7), inset 0 8px 14px rgba(255, 255, 255, 0.12), inset 0 -1px 0 rgba(255, 255, 255, 0.12), inset 1px 0 0 rgba(255, 255, 255, 0.15), inset -1px 0 0 rgba(255, 255, 255, 0.15);

  /* ── Metrics (Aqua 10.0 as measured; DESIGN.md front matter names each) ── */
  --y2k-menubar-h: 22px;
  --y2k-titlebar-h: 26px;
  --y2k-window-radius: 8px;
  --y2k-window-radius-bottom: 6px;
  --y2k-light-size: 13px;
  --y2k-light-gap: 5px;
  --y2k-statusbar-h: 24px;
  --y2k-button-h: 20px; /* push button height, fixed (small 17px) */
  --y2k-segment-h: 20px; /* ink; its shadow hangs 4px below */
  --y2k-segment-w: 25px; /* minimum segment; an icon segment exactly */
  --y2k-tab-h: 24px;
  --y2k-popup-h: 20px;
  --y2k-popup-gem: 21px;
  --y2k-bevel-h: 18px;
  --y2k-field-h: 24px;
  --y2k-check-cell-w: 15px; /* the check box's cell (16px tall), its 12px box inside */
  --y2k-radio-cell-w: 14px; /* the radio's cell … */
  --y2k-radio-cell-h: 15px; /* … and its height, the 12px ball inside */
  --y2k-slider-thumb: 15px;
  --y2k-slider-pointer-h: 19px;
  --y2k-stepper-w: 13px;
  --y2k-stepper-h: 21px;
  --y2k-progress-h: 20px; /* 16px groove + its 4px shadow */
  --y2k-dock-icon: 64px;
  --y2k-dock-h: 70px;

  /* ── Motion ───────────────────────────────────────────────────── */
  --y2k-ease-aqua: cubic-bezier(0.2, 0.8, 0.2, 1);
  --y2k-duration-window: 200ms;
}

/* ── Tones. Every gel, tab, control, progress and highlight gradient is the
      Aqua 10.0 lighting curve (see scripts/tones.mjs); Aqua takes it as
      measured, the other tones keep the curve in their own hue. ── */
/* measured:begin — generated by scripts/tones.mjs; edit the script, not this block. */
:root {
  --y2k-light-red: linear-gradient(to bottom, #050505 0px 1px, #d6cccc 1px 2px, #f3e6e6 2px 3px, #da9e9c 3px 4px, #c4554a 4px 5px, #d0574b 5px 6px, #e47264 6px 7px, #f8877c 7px 8px, #fe9b8e 8px 9px, #ffa89c 9px 10px, #ffb8ab 10px 11px, #fdbcaf 11px 12px, #e9836f 12px 13px);
  --y2k-light-yellow: linear-gradient(to bottom, #290505 0px 1px, #e1cccc 1px 2px, #f6ebe6 2px 3px, #e9c79c 3px 4px, #e1a034 4px 5px, #f0aa34 5px 6px, #f8bf4d 6px 7px, #fbd365 7px 8px, #fee975 8px 9px, #fffa82 9px 10px, #ffff92 10px 11px, #fdfd95 11px 12px, #e9e94d 12px 13px);
  --y2k-light-green: linear-gradient(to bottom, #050505 0px 1px, #cccdcc 1px 2px, #e6eee6 2px 3px, #adce9c 3px 4px, #6fae3a 4px 5px, #74b838 5px 6px, #8dcd52 6px 7px, #a3e069 7px 8px, #b8f67b 8px 9px, #c7ff89 9px 10px, #d6ff97 10px 11px, #d8fd9b 11px 12px, #aae955 12px 13px);
  --y2k-light-off: linear-gradient(to bottom, #050505 0px 1px, #cccccc 1px 2px, #eaebec 2px 3px, #c0c4c7 3px 4px, #939aa3 4px 5px, #98a0aa 5px 6px, #afb9c0 6px 7px, #c4ccd5 7px 8px, #d8dfeb 8px 9px, #ebf3fd 9px 10px, #faffff 10px 11px, #fbfdfd 11px 12px, #e0e9e9 12px 13px);
  --y2k-toolbar-toggle: linear-gradient(to bottom, #555555 0% 10%, #f7f7f7 10% 20%, #f4f4f4 20% 30%, #d8d8d8 30% 40%, #cacaca 40% 50%, #e0e0e0 50% 60%, #f9f9f9 60% 70%, #ffffff 70% 100%);
  --y2k-gel-white: linear-gradient(to bottom, #7c7c7c 0px 1px, #b4b4b4 1px 2px, #d2d2d2 2px 3px, #dcdcdc 3px 4px, #e1e1e1 4px 5px, #e5e5e5 5px 6px, #e3e3e3 6px 7px, #dbdbdb 7px 8px, #d6d6d6 8px 9px, #d9d9d9 9px 10px, #dddddd 10px 11px, #e5e5e5 11px 12px, #eeeeee 12px 13px, #f7f7f7 13px 14px, #ffffff 14px 19px, #f8f8f8 19px 20px);
  --y2k-gel-pressed: linear-gradient(to bottom, rgba(60,60,60,0.490) 0px 1px, rgba(88,88,88,0.490) 1px 2px, rgba(102,102,102,0.490) 2px 3px, rgba(107,107,107,0.490) 3px 4px, rgba(110,110,110,0.490) 4px 5px, rgba(112,112,112,0.490) 5px 6px, rgba(111,111,111,0.490) 6px 7px, rgba(107,107,107,0.490) 7px 8px, rgba(104,104,104,0.490) 8px 9px, rgba(106,106,106,0.490) 9px 10px, rgba(108,108,108,0.490) 10px 11px, rgba(112,112,112,0.490) 11px 12px, rgba(116,116,116,0.490) 12px 13px, rgba(121,121,121,0.490) 13px 14px, rgba(125,125,125,0.490) 14px 19px, rgba(121,121,121,0.490) 19px 20px);
  --y2k-segment-white: linear-gradient(to bottom, #a3a3a3 0px 1px, #dedede 1px 2px, #e7e7e7 2px 3px, #ebebeb 3px 4px, #e9e9e9 4px 5px, #e6e6e6 5px 6px, #e5e5e5 6px 8px, #eaeaea 8px 9px, #efefef 9px 10px, #f1f1f1 10px 11px, #f3f3f3 11px 12px, #f6f6f6 12px 13px, #f9f9f9 13px 14px, #fdfdfd 14px 16px, #ffffff 16px 20px);
  --y2k-segment-pressed: linear-gradient(to bottom, #646464 0px 1px, #b8b8b8 1px 2px, #c5c5c5 2px 3px, #cbcbcb 3px 4px, #c8c8c8 4px 5px, #c3c3c3 5px 6px, #c2c2c2 6px 8px, #c9c9c9 8px 9px, #d0d0d0 9px 10px, #d3d3d3 10px 11px, #d6d6d6 11px 12px, #dadada 12px 13px, #dedede 13px 14px, #e4e4e4 14px 16px, #e7e7e7 16px 20px);
  --y2k-segment-divider: linear-gradient(to bottom, #747474 0px 1px, #b9b9b9 1px 2px, #cccccc 2px 3px, #c7c7c7 3px 4px, #bbbbbb 4px 5px, #a4a4a4 5px 6px, #9a9a9a 6px 8px, #a0a0a0 8px 9px, #a8a8a8 9px 10px, #b1b1b1 10px 11px, #bababa 11px 12px, #c4c4c4 12px 13px, #cacaca 13px 14px, #cfcfcf 14px 15px, #dadada 15px 16px, #dfdfdf 16px 20px);
  --y2k-listheader: linear-gradient(to bottom, #959595 0px 1px, #bebebe 1px 2px, #d3d3d3 2px 3px, #dbdbdb 3px 4px, #dddddd 4px 5px, #dadada 5px 6px, #d3d3d3 6px 7px, #d9d9d9 7px 8px, #e0e0e0 8px 9px, #e9e9e9 9px 10px, #f3f3f3 10px 11px, #f9f9f9 11px 12px, #fefefe 12px 13px, #ffffff 13px 16px, #999999 16px 17px);
  --y2k-check-off: linear-gradient(to bottom, #cacaca 0px 1px, #d6d6d6 1px 2px, #c0c0c0 2px 3px, #b9b9b9 3px 4px, #c5c5c5 4px 5px, #d1d1d1 5px 6px, #dcdcdc 6px 7px, #e6e6e6 7px 8px, #f2f2f2 8px 9px, #fbfbfb 9px 10px, #ffffff 10px 11px, rgba(170,170,170,0.941) 11px 12px);
  --y2k-radio-off: linear-gradient(to bottom, rgba(54,54,54,0.937) 0px 1px, #999999 1px 2px, #d1d1d1 2px 4px, #c0c0c0 4px 5px, #c3c3c3 5px 6px, #d5d5d5 6px 7px, #e4e4e4 7px 8px, #f2f2f2 8px 9px, #ffffff 9px 10px, #fefefe 10px 11px, #ffffff 11px 12px, rgba(166,166,166,0.922) 12px 13px);
  --y2k-popup-white: linear-gradient(to bottom, #a3a3a3 0px 1px, #dedede 1px 2px, #e9e9e9 2px 3px, #eaeaea 3px 5px, #e6e6e6 5px 6px, #e7e7e7 6px 7px, #ebebec 7px 8px, #efefef 8px 9px, #f1f1f1 9px 10px, #f3f3f3 10px 12px, #f5f5f5 12px 13px, #f8f8f9 13px 14px, #fefefb 14px 15px, #fefefe 15px 16px, #ffffff 16px 20px);
  --y2k-stepper: linear-gradient(to bottom, #646464 0px 1px, #d0d0d0 1px 2px, #e3e3e3 2px 3px, #e0e0e0 3px 4px, #d4d4d4 4px 5px, #c1c1c1 5px 6px, #b8b8b8 6px 7px, #bfbfbf 7px 8px, #c8c8c8 8px 9px, #d0d0d0 9px 10px, #d6d6d6 10px 11px, #dedede 11px 12px, #e3e3e3 12px 13px, #eeeeee 13px 14px, #f2f2f2 14px 15px, #fbfbfb 15px 16px, #ffffff 16px 20px, #ececec 20px 21px);
  --y2k-progress-track: linear-gradient(to bottom, #a3a3a3 0px 1px, #d2d2d2 1px 2px, #e3e3e3 2px 3px, #e7e7e7 3px 5px, #dedede 5px 6px, #d9d9d9 6px 7px, #dedede 7px 8px, #e3e3e3 8px 9px, #e9e9e9 9px 10px, #f0f0f0 10px 11px, #f4f4f4 11px 12px, #f6f6f6 12px 13px, #f7f7f7 13px 14px, #f8f8f8 14px 15px, #cecece 15px 16px, rgba(0,0,0,0.259) 16px 17px, rgba(0,0,0,0.196) 17px 18px, rgba(0,0,0,0.098) 18px 19px, rgba(0,0,0,0.031) 19px 20px);
  --y2k-slider-track: linear-gradient(to bottom, #535353 0px 1px, #737373 1px 2px, #939393 2px 3px, #a8a8a8 3px 4px, #b6b6b6 4px 5px, #c3c3c3 5px 6px, #cacaca 6px 7px);
  --y2k-titlebar: linear-gradient(to bottom, #ffffff 0px 2px, #f1f1f1 2px 3px, #eaeaea 3px 4px, #f1f1f1 4px 5px, #fefefe 5px 6px, #f0f0f0 6px 7px, #e9e9e9 7px 8px, #efefef 8px 9px, #fdfdfd 9px 10px, #eeeeee 10px 11px, #e6e6e6 11px 12px, #ececec 12px 13px, #f8f8f8 13px 14px, #e8e8e8 14px 15px, #e0e0e0 15px 16px, #e4e4e4 16px 17px, #efefef 17px 18px, #e1e1e1 18px 19px, #d9d9d9 19px 20px, #dedede 20px 21px, #efefef 21px 22px, #e1e1e1 22px 23px, #d9d9d9 23px 24px, #dedede 24px 25px, #7f7f7f 25px 26px);
  --y2k-titlebar-inactive: linear-gradient(to bottom, rgba(191,191,191,0.749) 0px 2px, rgba(180,180,180,0.749) 2px 3px, rgba(175,175,175,0.749) 3px 4px, rgba(180,180,180,0.749) 4px 5px, rgba(190,190,190,0.749) 5px 6px, rgba(179,179,179,0.749) 6px 7px, rgba(174,174,174,0.749) 7px 8px, rgba(179,179,179,0.749) 8px 9px, rgba(189,189,189,0.749) 9px 10px, rgba(178,178,178,0.749) 10px 11px, rgba(172,172,172,0.749) 11px 12px, rgba(176,176,176,0.749) 12px 13px, rgba(185,185,185,0.749) 13px 14px, rgba(173,173,173,0.749) 14px 15px, rgba(167,167,167,0.749) 15px 16px, rgba(170,170,170,0.749) 16px 17px, rgba(179,179,179,0.749) 17px 18px, rgba(168,168,168,0.749) 18px 19px, rgba(162,162,162,0.749) 19px 20px, rgba(166,166,166,0.749) 20px 21px, rgba(179,179,179,0.749) 21px 22px, rgba(168,168,168,0.749) 22px 23px, rgba(162,162,162,0.749) 23px 24px, rgba(166,166,166,0.749) 24px 25px, #7f7f7f 25px 26px);
  --y2k-round-button: linear-gradient(to bottom, rgba(80,80,80,0.953) 0% 5%, #919191 5% 10%, #cccccc 10% 15%, #e3e3e3 15% 20%, #e9e9e9 20% 25%, #e6e6e6 25% 30%, #dfdfdf 30% 35%, #dddddd 35% 45%, #e4e4e4 45% 50%, #ebebeb 50% 55%, #f6f6f6 55% 60%, #fefefe 60% 65%, #ffffff 65% 95%, #f5f5f5 95% 100%);
  --y2k-metal-button: linear-gradient(to bottom, #adadad 0% 3.13%, #ffffff 3.13% 12.5%, #e7e7e7 12.5% 15.63%, #dedede 15.63% 18.75%, #efefef 18.75% 31.25%, #f7f7f7 31.25% 40.63%, #ffffff 40.63% 96.88%, #7b7b7b 96.88% 100%);
  --y2k-metal-groove: linear-gradient(to bottom, #636363 0px 1px, #737373 1px 2px, #949494 2px 3px, #b5b5b5 3px 4px, #d6d6d6 4px 5px, #e7e7e7 5px 6px);
  --y2k-metal-knob: linear-gradient(to bottom, #7b7b7b 0% 7.69%, #cecece 7.69% 15.38%, #efefef 15.38% 23.08%, #f7f7f7 23.08% 30.77%, #e7e7e7 30.77% 38.46%, #dedede 38.46% 46.15%, #efefef 46.15% 53.85%, #ffffff 53.85% 84.62%, #f7f7f7 84.62% 92.31%, #7b7b7b 92.31% 100%);
  --y2k-bevel: linear-gradient(to bottom, #bfbfbf 0px 1px, #f4f4f4 1px 2px, #f7f7f7 2px 3px, #f7f7f7 3px 4px, #f5f5f5 4px 5px, #ececec 5px 6px, #ebebeb 6px 7px, #ececec 7px 8px, #ebebeb 8px calc(100% - 8px), #efefef calc(100% - 8px) calc(100% - 7px), #f3f3f3 calc(100% - 7px) calc(100% - 6px), #fafafa calc(100% - 6px) calc(100% - 5px), #ffffff calc(100% - 5px) calc(100% - 4px), #ffffff calc(100% - 4px) calc(100% - 3px), #ffffff calc(100% - 3px) calc(100% - 2px), #ffffff calc(100% - 2px) calc(100% - 1px), rgba(0,0,0,0.686) calc(100% - 1px) calc(100% - 0px));
