/* tones:end */

/* Composite gradients are re-declared on every toned element so a swatch with
   its own data-tone renders in its own tone (custom properties resolve where
   they are declared, not where they are used). */
:root,
[data-tone] {
  --y2k-focus-ring: 0 0 0 3px var(--y2k-tone-focus);
  --y2k-button-rim-tone: inset 6px 0 7px -4px color-mix(in srgb, var(--y2k-tone-button-edge) 70%, transparent), inset -6px 0 7px -4px color-mix(in srgb, var(--y2k-tone-button-edge) 70%, transparent);
}

/* Selected text takes the tone's selection, as Aqua's text highlight did —
   never the browser's own blue. */
::selection {
  background: var(--y2k-tone-selection);
  color: var(--y2k-tone-selection-text);
}

/* Range-input parts, one class list for both engines: thumb:size-… track:h-… */
@custom-variant thumb {
  &::-webkit-slider-thumb { @slot; }
  &::-moz-range-thumb { @slot; }
}
@custom-variant track {
  &::-webkit-slider-runnable-track { @slot; }
  &::-moz-range-track { @slot; }
}

/* ── Keyframes ────────────────────────────────────────────────────── */
@keyframes y2k-window-in {
  from { scale: 0.95; opacity: 0; }
  to   { scale: 1;    opacity: 1; }
}
@keyframes y2k-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
/* The default button's dialog throb (opt-in: Button pulsing). */
@keyframes y2k-pulse {
  0%, 100% { filter: brightness(0.94) saturate(1.05); }
  50%      { filter: brightness(1.22) saturate(1.15) contrast(1.05); }
}
/* Progress: the stripe layer (starting one period left of the bar) slides
   right by one period — 32px for the barber pole, 16px for the ribs — on the
   compositor, stepped like the original's frames. */
@keyframes y2k-barber {
  from { transform: translateX(0); }
  to   { transform: translateX(32px); }
}
@keyframes y2k-ribs {
  from { transform: translateX(0); }
  to   { transform: translateX(16px); }
}
/* Terminal's block cursor. */
@keyframes y2k-blink {
  50% { opacity: 0; }
}
/* Old-web scrolling marquee: the content track slides fully left, then loops. */
@keyframes y2k-marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}
/* MSN "Nudge": the toast slides up from the Dock, then shakes once. */
@keyframes y2k-nudge-in {
  0%   { transform: translateY(120%); opacity: 0; }
  60%  { transform: translateY(0);    opacity: 1; }
  68%  { transform: translate(-4px, 0); }
  76%  { transform: translate(4px, 0); }
  84%  { transform: translate(-3px, 0); }
  92%  { transform: translate(2px, 0); }
  100% { transform: translate(0, 0); }
}
@keyframes y2k-nudge-out {
  from { transform: translateY(0);    opacity: 1; }
  to   { transform: translateY(120%); opacity: 0; }
}
/* The Dock icon of an app that is starting: up half its height, slowing,
   then down again, speeding; the Dock runs it twice. */
@keyframes y2k-dock-bounce {
  0%   { transform: translateY(0); animation-timing-function: cubic-bezier(0.25, 0.6, 0.4, 1); }
  50%  { transform: translateY(-32px); animation-timing-function: cubic-bezier(0.6, 0, 0.75, 0.4); }
  100% { transform: translateY(0); }
}
/* Desktop sparkle: a star glint that fades fully in then out with a scale
   pulse. Fades to 0 at the loop boundary so the desktop layer can relocate the
   glint between flashes (each twinkle appears in a new random spot). */
@keyframes y2k-twinkle {
  0%, 100% { opacity: 0; transform: scale(0.5); }
  50%      { opacity: 1; transform: scale(1); }
}

/* ── Materials ───────────────────────────────────────────────────── */

/* Surfaces: the Aqua materials as plain classes, for markup without Tailwind.
   Light pinstripe (menus), pinstripe (windows), dark pinstripe (sheets). */
.y2k-pinstripe-light { background-image: var(--y2k-pinstripe-light); }
.y2k-pinstripe { background-image: var(--y2k-pinstripe); }
.y2k-pinstripe-dark { background-image: var(--y2k-pinstripe-dark); }

/* Component classes sit in the components layer, so a utility on the same
   element (focus:border-…, px-…) still wins over them. */
@layer components {
  /* A sunken white field: text fields, tree views, the Terminal's page. */
  .y2k-field {
    border: 1px solid var(--y2k-field-border);
    border-top-color: var(--y2k-field-border-top);
    border-radius: 2px;
    background: #ffffff;
    box-shadow: var(--y2k-field-shadow);
  }

  /* The group box: a faint grey well in a #b6b6b6 rim with 5px corners, its
     bold 12px caption set into the top border 20px in. */
  .y2k-group {
    min-width: 0;
    border: 1px solid #b6b6b6;
    border-radius: 5px;
    background: rgba(129, 129, 129, 0.1);
    padding: 16px 20px 20px;
  }
  .y2k-group > legend {
    padding: 0 5px;
    font-size: 12px;
    font-weight: 700;
  }
}

/* Brushed aluminum (iTunes / Finder in Tiger). Neutral, so a static texture. */
.y2k-metal {
  background-color: #c9c9c9;
  background-image: var(--y2k-metal);
  background-size: 512px 96px;
}

/* Gel wordmark text: tone gradient clipped to glyphs. */
.y2k-gel-text {
  background: var(--y2k-tone-list);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 1px 0 rgba(255, 255, 255, 0.7));
}
